"""The marketing site (generated by build.py): home page, search landing pages and policy pages."""
from __future__ import annotations

import re
from functools import lru_cache
from pathlib import Path

from fastapi import APIRouter, Request
from fastapi.responses import FileResponse, HTMLResponse, JSONResponse

import landing_pages

from ..config import Settings, get_settings
from ..db import tx
from .deps import TEMPLATES

ROOT = Path(__file__).resolve().parent.parent.parent
router = APIRouter(tags=["site"])
ANALYTICS_SLOT = "<!--ANALYTICS-->"

# Consent Mode v2 defaults. Analytics is on; advertising signals are withheld when the
# browser sends Global Privacy Control (a recognised opt-out under several US state laws).
CONSENT = ("<script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments);}"
           "var gpc=navigator.globalPrivacyControl===true;"
           "gtag('consent','default',{ad_storage:gpc?'denied':'granted',ad_user_data:gpc?'denied':'granted',"
           "ad_personalization:gpc?'denied':'granted',analytics_storage:'granted'});</script>")


def analytics_snippet(s: Settings) -> str:
    """Google Tag Manager if configured, else direct GA4, else nothing. IDs are validated
    so a mistyped environment value can never inject markup into the page."""
    if re.fullmatch(r"GTM-[A-Z0-9]{4,12}", s.gtm_container_id or ""):
        return CONSENT + (
            "<script>(function(w,d,s,l,i){w[l]=w[l]||[];w[l].push({'gtm.start':new Date().getTime(),event:'gtm.js'});"
            "var f=d.getElementsByTagName(s)[0],j=d.createElement(s);j.async=true;"
            f"j.src='https://www.googletagmanager.com/gtm.js?id='+i;f.parentNode.insertBefore(j,f);}})"
            f"(window,document,'script','dataLayer','{s.gtm_container_id}');</script>")
    if re.fullmatch(r"G-[A-Z0-9]{4,15}", s.ga4_measurement_id or ""):
        return CONSENT + (
            f'<script async src="https://www.googletagmanager.com/gtag/js?id={s.ga4_measurement_id}"></script>'
            f"<script>window.__mrDirectGA=true;gtag('js',new Date());gtag('config','{s.ga4_measurement_id}');</script>")
    return ""


@lru_cache(maxsize=None)
def built_html(name: str) -> str:
    """A built page with the analytics tags for this environment (cached per process)."""
    return (ROOT / name).read_text().replace(ANALYTICS_SLOT, analytics_snippet(get_settings()))


def index_html() -> str:
    return built_html("index.html")


PAGE_CACHE = {"Cache-Control": "public, max-age=300"}


@router.api_route("/", methods=["GET", "HEAD"], include_in_schema=False)
def home():
    return HTMLResponse(index_html(), headers=PAGE_CACHE)


def _landing_route(path: str):
    name = f"pages{path}.html"          # matches marketing.page.landing_file

    def handler():
        return HTMLResponse(built_html(name), headers=PAGE_CACHE)
    handler.__name__ = "landing" + re.sub(r"\W", "_", path)
    router.add_api_route(path, handler, methods=["GET", "HEAD"], include_in_schema=False)


# Registered before the one-segment policy-page route below, which would otherwise shadow them.
for _page in landing_pages.PAGES:
    _landing_route(_page["path"])


PUBLIC_FILES = {
    "/pricing.md": ("pricing.md", "text/markdown; charset=utf-8", 3600),
    "/robots.txt": ("robots.txt", "text/plain; charset=utf-8", 3600),
    "/sitemap.xml": ("sitemap.xml", "application/xml", 3600),
}
LEGAL = {"terms": "Terms of service", "privacy": "Privacy policy", "accessibility": "Accessibility"}


def _file_route(path: str, name: str, media: str, max_age: int):
    def handler():
        return FileResponse(ROOT / name, media_type=media, headers={"Cache-Control": f"public, max-age={max_age}"})
    handler.__name__ = "file_" + name.replace(".", "_")
    router.add_api_route(path, handler, methods=["GET", "HEAD"], include_in_schema=False)


for _path, (_name, _media, _age) in PUBLIC_FILES.items():
    _file_route(_path, _name, _media, _age)


@router.get("/healthz", include_in_schema=False)
def health():
    with tx() as conn:
        conn.execute("SELECT 1")
    return JSONResponse({"ok": True})


@router.get("/{page}", response_class=HTMLResponse, include_in_schema=False)
def legal(request: Request, page: str):
    if page not in LEGAL:
        return TEMPLATES.TemplateResponse(request, "error.html", {"message": "Page not found."}, status_code=404)
    return TEMPLATES.TemplateResponse(request, f"legal/{page}.html", {
        "title": LEGAL[page], "approved": get_settings().legal_pages_approved})
